const ROSTER_RANK = { junior: 0, officer: 1, senior: 1, chief: 2, xo: 3, captain: 4, guest: 0 };
// a guest in plain clothes (GUESTS, uniform null) carries its own spec: dept 'civilian' and an outfit colour
